/**
 * Read the first recorded example of ChildA with the content
 * of the element `xmlName` replaced by `text`.
 */
function readEitherWith(
  xmlName: string,
  text: string
): ReturnType<typeof OurXmlization.fromXmlString> {
  const pths = Array.from(
    TestCommon.findFilesBySuffixRecursively(
      path.join(
        TestCommon.TEST_DATA_DIR,
        "Xml",
        "Expected",
        "childA"
      ),
      ".xml"
    )
  );
  pths.sort();

  expect(pths.length).toBeGreaterThan(0);

  const original = fs.readFileSync(pths[0], "utf-8");

  const start = original.indexOf(`<${xmlName}>`) + xmlName.length + 2;
  const end = original.indexOf(`</${xmlName}>`);

  const patched = original.slice(0, start) + text + original.slice(end);

  return OurXmlization.fromXmlString(patched);
}

/**
 * Read the first recorded example of ChildA with the content
 * of the element `xmlName` replaced by `text`, and expect no error.
 */
function readWith(xmlName: string, text: string): OurTypes.ChildA {
  const instanceOrError = readEitherWith(xmlName, text);
  expect(instanceOrError.error).toBeNull();

  const casted = OurTypes.asChildA(instanceOrError.mustValue());
  if (casted === null) {
    throw new Error(`Expected an instance of ChildA`);
  }

  return casted;
}

test("number read at the bounds of the safe integer range", () => {
  for (const text of ["9007199254740991", "-9007199254740991"]) {
    const instance = readWith("number", text);
    expect(instance.number).toBe(Number(text));
  }
});

test("number refused outside the safe integer range", () => {
  for (const text of ["9007199254740992", "-9007199254740992"]) {
    const instanceOrError = readEitherWith("number", text);
    expect(instanceOrError.error?.message).toStrictEqual(
      `Expected an integer, but got ${text}, ` +
        "which is outside the safe integer range [-2^53 + 1, 2^53 - 1]"
    );
  }
});

